 ShaderMaterial WoodlandLeaves(){return woodlandLeaves??=new ShaderMaterial{Shader=GD.Load<Shader>("res://Shaders/woodland-leaves.gdshader")};}
 void ArtPine(Node3D root,float h,int seed){Tube(root,Vector3.Zero,new(.04f,h*.91f,0),.27f,Wood,.045f).MaterialOverride=Textured(Wood,0,.8f);PhysicsObstacle(root,new CylinderShape3D{Radius=.45f,Height=h*.65f},new(0,h*.325f,0));for(int i=0;i<5;i++){float y=h*(.40f+i*.105f),radius=h*(.22f-i*.031f);var m=new MeshInstance3D{Mesh=new CylinderMesh{TopRadius=.035f,BottomRadius=radius,Height=h*.29f,RadialSegments=15,Rings=2},Position=new(0,y,0),MaterialOverride=WoodlandLeaves(),VisibilityRangeEnd=210};root.AddChild(m);}} ShaderMaterial meadowGrass;
 void LivingGrass(Node3D root,int cx,int cz){if(grassMesh==null){var b=new SurfaceTool();b.Begin(Mesh.PrimitiveType.Triangles);for(int j=0;j<7;j++){float a=j*2.4f;var side=new Vector3(Mathf.Cos(a)*.022f,0,Mathf.Sin(a)*.022f);var foot=new Vector3(Mathf.Sin(a)*.10f,0,Mathf.Cos(a)*.10f);var mid=foot+new Vector3(.025f,.20f+j*.012f,.01f);var tip=foot+new Vector3(.10f,.34f+j*.017f,.04f);foreach(var p in new[]{foot-side,foot+side,mid+side*.6f,foot-side,mid+side*.6f,mid-side*.6f,mid-side*.6f,mid+side*.6f,tip}){b.SetNormal(new Vector3(.15f,1,.10f).Normalized());b.AddVertex(p);}}grassMesh=b.Commit();}
  var r=new Random(unchecked((int)game.World.Hash(cx+537,cz)));var points=new List<Vector3>();for(int i=0;i<900;i++){double x=cx*64+r.NextDouble()*64,z=cz*64+r.NextDouble()*64;if(SuburbPaved(x,z)||InEncounterLot(x,z)||InCrashLot(x,z)||InCheckpointLot(x,z)||InBirthdayLot(x,z)||InLetterLot(x,z)||!game.World.Playable(x,z)||game.World.Tier(x,z)>2||Math.Abs(x-game.World.RouteX(z))<6||game.World.Changes.OnPath(x,z))continue;points.Add(Ground(x,z));}var mm=new MultiMesh{TransformFormat=MultiMesh.TransformFormatEnum.Transform3D,Mesh=grassMesh,UseColors=true,InstanceCount=points.Count};for(int i=0;i<points.Count;i++){mm.SetInstanceTransform(i,new Transform3D(Basis.FromEuler(new Vector3(0,(float)r.NextDouble()*6,0)).Scaled(Vector3.One*(.55f+(float)r.NextDouble()*.7f)),points[i]));float shade=.75f+(float)r.NextDouble()*.3f;mm.SetInstanceColor(i,new(shade,shade,shade,1));}meadowGrass??=new ShaderMaterial{Shader=GD.Load<Shader>("res://Shaders/meadow-grass.gdshader")};root.AddChild(new MultiMeshInstance3D{Multimesh=mm,MaterialOverride=meadowGrass,CastShadow=GeometryInstance3D.ShadowCastingSetting.Off,VisibilityRangeEnd=110});
 }
 void WorldDetails(Node3D root,int cx,int cz,bool simulation){var r=new Random(unchecked((int)game.World.Hash(cx+211,cz-751)));for(int i=0;i<5;i++){double x=cx*64+8+r.NextDouble()*48,z=cz*64+8+r.NextDouble()*48;int tier=game.World.Tier(x,z);if(SuburbPaved(x,z)||InEncounterLot(x,z)||InCrashLot(x,z)||InCheckpointLot(x,z)||InBirthdayLot(x,z)||InLetterLot(x,z)||!game.World.Playable(x,z)||Math.Abs(x-game.World.RouteX(z))<8||game.World.BuildingCell(Math.Floor(x/32)*32+16,Math.Floor(z/32)*32+16))continue;var p=Ground(x,z);if(tier==2&&i<2){if(simulation)continue;Tube(root,p+new Vector3(-.8f,.12f,0),p+new Vector3(.9f,.16f,.25f),.14f,Wood);for(int j=0;j<7;j++){float a=j*2.4f;Tube(root,p,p+new Vector3(Mathf.Sin(a)*.5f,.25f,Mathf.Cos(a)*.5f),.035f,new Color(.23f,.32f,.15f),.008f);}}else if(!simulation&&tier<=2){for(int j=0;j<5;j++){var f=p+new Vector3(j*.18f,0,Mathf.Sin(j)*.18f);Tube(root,f,f+Vector3.Up*.28f,.009f,Leaf);Ellipsoid(root,f+Vector3.Up*.28f,new(.045f,.025f,.045f),i%2==0?new Color(.65f,.57f,.31f):new Color(.60f,.58f,.51f));}}else if(tier>=3){if(simulation)continue;for(int j=0;j<3;j++)Bevel(root,p+new Vector3(j*.35f,.12f,0),new(.3f,.24f,.4f),new Color(.33f,.32f,.28f));}}
  for(int z=cz*64;z<(cz+1)*64;z+=16){double x=game.World.RouteX(z)+11;if(x<cx*64||x>=(cx+1)*64||!game.World.Playable(x,z))continue;var p=Ground(x,z);if(game.World.Tier(x,z)<=2){if(simulation)continue;Tube(root,p,p+Vector3.Up*1.15f,.045f,Wood);for(int j=0;j<2;j++)Tube(root,p+Vector3.Up*(.45f+j*.45f),Ground(game.World.RouteX(z+14)+11,z+14)+Vector3.Up*(.45f+j*.45f),.035f,Wood);}else if((z%64+64)%64==0){if(simulation){PhysicsObstacle(root,new BoxShape3D{Size=new(.7f,1.1f,.7f)},p+Vector3.Up*.55f);continue;}Box(root,p+Vector3.Up*.55f,new(.7f,1.1f,.7f),Steel,true);Box(root,p+new Vector3(0,.9f,-.36f),new(.55f,.12f,.025f),Ink);}}
