 double supplyDue;int supplyX=int.MinValue,supplyZ=int.MinValue,supplySeed;
 void ExpeditionSupplies(bool force=false){int scx=(int)Math.Floor(player.Position.X/128),scz=(int)Math.Floor(player.Position.Z/128);if(!force&&game.Clock<supplyDue&&scx==supplyX&&scz==supplyZ&&supplySeed==game.Save.Seed)return;supplyDue=game.Clock+.75;supplyX=scx;supplyZ=scz;supplySeed=game.Save.Seed;foreach(var p in props.ToArray())if(p.Kind==9&&game.Craft.Gathered.Contains(p.Id)){uniqueObjects.Remove(p.Id);worldRoot.RemoveChild(p.Node);p.Node.QueueFree();props.Remove(p);}int cx=(int)Math.Floor(player.Position.X/128),cz=(int)Math.Floor(player.Position.Z/128);for(int dx=-1;dx<=1;dx++)for(int dz=-1;dz<=1;dz++){int x=cx+dx,z=cz+dz;uint h=game.World.Hash(x+823,z-117);if(h%3==0)continue;double xx=x*128+20+h%80,zz=z*128+20+(h>>8)%80;if(!OutdoorFree(xx,zz)||Distance(Ground(xx,zz),player.Position)>150)continue;string id=$"supplies/{game.Save.Seed}/{x}:{z}";if(uniqueObjects.Contains(id)||game.Craft.Gathered.Contains(id))continue;uniqueObjects.Add(id);int tier=game.World.Tier(xx,zz);var n=new Node3D{Position=Ground(xx,zz)};worldRoot.AddChild(n);Box(n,new(0,.3f,0),new(.95f,.6f,.65f),Wood);Box(n,new(0,.63f,0),new(1,.08f,.7f),Wood);for(int s=-1;s<=1;s+=2)Box(n,new(s*.32f,.32f,-.34f),new(.04f,.6f,.025f),Steel);n.AddChild(new Label3D{Text="SUPPLIES",Position=new(0,.44f,-.36f),FontSize=20,PixelSize=.006f,Modulate=new(.76f,.71f,.53f)});props.Add(new WorldProp{Id=id,Kind=9,Tier=tier,Material=tier==1?(int)(h%3):tier+1,Amount=2+(int)(h%3),Position=n.Position,Node=n});}}
 bool SearchSupply(){var p=NearProp(9,2.6f);if(p==null)return false;if(game.Change(()=>{if(game.Craft.Gathered.Contains(p.Id))return;game.Craft.Gathered.Add(p.Id);game.Craft.Materials[p.Material]+=p.Amount;game.Craft.UnlockedTier=Math.Max(game.Craft.UnlockedTier,p.Tier);game.Life.Food++;if(p.Tier>=3)game.Craft.GiveAmmo(p.Tier>=5?4:p.Tier==4?1:2,6);game.Skills.Survival.Gain(20);})){game.Notice="Supplies recovered / materials and provisions";TryScavengeTrap(p);ExpeditionSupplies(true);}return true;}
